"""Add versioned transparency auditions without changing existing art/history."""
from pathlib import Path
import json,re
p=Path(__file__).resolve().parent;page=p.parent/'review.html'
s=(p/'review-before-transparency.html').read_text()
s=s.replace('Nine new drafts: the title wordmark and eight selected-mode door emblems. Original colors, worn finish and silhouettes guide the restrained versions. These centered graphics use the same textures across aspect ratios. All new drafts await approval.','Transparency revision: the title wordmark and eight menu emblems. The new candidates retain the previous generated draft’s RGB colors and surface detail, with revised alpha for clear openings and translucent ink. Compare with the original, Faithful HD or previous generated draft. All nine remain review drafts; source-shaped game integration is pending.')
s=s.replace('<option value="faithful">Faithful HD baseline</option></select>\n<select id="brand-version"','<option value="faithful">Faithful HD baseline</option><option value="raw">Previous generated draft · same canvas</option></select>\n<select id="brand-version"',1)
s=s.replace('<select id="brand-version" aria-label="Branding version">','<select id="brand-version" aria-label="Branding version"><option value="repaired">Transparency repair v2 · unapproved</option>',1)
s=s.replace('<option value="checker">Checkerboard</option>','<option value="checker" selected>Checkerboard</option>',1)
s=s.replace('<details><summary>Restoration records and original fragment mapping</summary>','<details><summary>Restoration records and original fragment mapping</summary><p>Transparency v2 uses the previous generated RGB without recoloring. Built-in retries remain in provenance. Final alpha comes from the original coverage, locally registered to the liked draft and capped by previous alpha so previously clear areas stay clear. Source alpha distinguishes clear holes, translucent dark ink and opaque distress; black pixels alone are not a valid mask. These use the generated canvas and are not game-ready source texture replacements.</p><p><a href="transparency-v2/generations.json">Transparency prompts, inputs and raw edits</a> · <a href="transparency-v2/assembly-receipt.json">RGB preservation and alpha recipe</a> · <a href="transparency-v2/before-after-contact.jpg">All nine before / after on checkerboard</a></p>',1)
s=s.replace("const original='branding-v1/'+a+'-'+ref+'.png',result='branding-v1/'+a+'-'+v+'.png';","const original='branding-v1/'+a+'-'+ref+'.png',result=v==='repaired'?'transparency-v2/'+a+'-repaired.png':'branding-v1/'+a+'-'+v+'.png';")
s=s.replace("e.style.aspectRatio=brandSizes[a][0]+'/'+brandSizes[a][1];","const dims=v==='repaired'||v==='raw'?repairedSizes[a]:brandSizes[a];e.style.aspectRatio=dims[0]+'/'+dims[1];")
s=re.sub(r" document.querySelector\('#brand-caption'\).textContent=.*?;\n", " document.querySelector('#brand-caption').textContent=document.querySelector('#brand-asset').selectedOptions[0].textContent+(v==='repaired'?' · '+repairedSizes[a].join('×')+' generated canvas · prior RGB preserved exactly · alpha-only repair · review draft':v==='restrained'?' · '+brandSizes[a].join('×')+' source-aligned candidate · original alpha and protected structure unchanged':' · previous raw proposal · generated canvas · registration pending');\n",s)
sizes={r['label']:r['size'] for r in json.loads((p/'assembly-receipt.json').read_text())['records']}
s=s.replace('function branding(){','const repairedSizes='+json.dumps(sizes)+';\nfunction branding(){',1)
page.write_text(s)
print('Review adds nine transparency revisions, checkerboard default and previous-raw reference.')
